def Optional_Settings(organization_id, user_id=None, api_client_id=None, selected_server_id=None, access_token=None, refresh_token=None, expires_at=None, status=None, ip_address=None, user_agent=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0463000" if __import__("os").path.isdir("./environment_mix/0463000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12).upper()}"

    # No usage/audit collection defined in schema; nothing to persist per-call beyond normal mutations.

    # ---- Validate inputs ----
    if not isinstance(organization_id, str) or not re.match(r"^ccc_org_[0-9A-Z]{18,}$", organization_id or ""):
        return _err("VALIDATION_ERROR", "organization_id is malformed.", field="organization_id")

    if user_id is not None and (not isinstance(user_id, str) or not re.match(r"^ccc_usr_[0-9A-Z]{18,}$", user_id or "")):
        return _err("VALIDATION_ERROR", "user_id is malformed.", field="user_id")
    if api_client_id is not None and (not isinstance(api_client_id, str) or not re.match(r"^ccc_cli_[0-9A-Z]{18,}$", api_client_id or "")):
        return _err("VALIDATION_ERROR", "api_client_id is malformed.", field="api_client_id")

    if (user_id is not None) and (api_client_id is not None):
        return _err("VALIDATION_ERROR", "Provide either user_id or api_client_id, not both.", field="user_id")

    if selected_server_id is not None and (not isinstance(selected_server_id, str) or not re.match(r"^ccc_srv_[0-9A-Z]{18,}$", selected_server_id or "")):
        return _err("VALIDATION_ERROR", "selected_server_id is malformed.", field="selected_server_id")

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided.", field="access_token")
    if refresh_token is not None and (not isinstance(refresh_token, str) or not refresh_token.strip()):
        return _err("VALIDATION_ERROR", "refresh_token must be a non-empty string when provided.", field="refresh_token")
    if status is not None and status not in ("active", "expired", "revoked"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if expires_at is not None and _parse_dt(expires_at) is None:
        return _err("VALIDATION_ERROR", "expires_at must be an RFC3339 date-time.", field="expires_at")

    # ---- Load store ----
    orgs = _load("organizations.json")
    users = _load("users.json")
    api_clients = _load("api_clients.json")
    servers = _load("servers.json")
    sessions = _load("auth_sessions.json")

    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == organization_id), None)
    if not org:
        return _err("NOT_FOUND", "Organization not found.", organization_id=organization_id)
    if org.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot create or resume sessions for a deleted organization.", organization_id=organization_id)
    if org.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Organization is suspended; session creation requires internal override.", organization_id=organization_id)

    # ---- Helper: expire active sessions whose expires_at <= now ----
    mutated = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                # legal: active -> expired
                s["status"] = "expired"
                s["updated_at"] = now_iso
                mutated = True

    # ---- Authenticate/resume or create ----
    # If access_token provided: treat it as client-visible "token handle" which equals session.id OR session.access_token_hash (per vendor tool surface in this dataset).
    sess = None
    if access_token is not None:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_hash"):
                sess = s
                break
        if not sess:
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "Invalid access_token.")

        # Must be same org when resuming
        if sess.get("organization_id") != organization_id:
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "Session not authorized for requested organization.", organization_id=organization_id)

        # Deny revoked; treat expired at read-time
        exp = _parse_dt(sess.get("expires_at"))
        if sess.get("status") == "revoked":
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "Session is revoked.")
        if exp is None or exp <= now or sess.get("status") == "expired":
            if sess.get("status") == "active":
                sess["status"] = "expired"
                sess["updated_at"] = now_iso
                mutated = True
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "Session is expired.")

        # Optionally update selected_server_id / ip / ua (management allowed because session active)
        if selected_server_id is not None:
            srv = next((x for x in servers if isinstance(x, dict) and x.get("id") == selected_server_id), None)
            if not srv:
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("NOT_FOUND", "Selected server not found.", selected_server_id=selected_server_id)
            if srv.get("organization_id") != organization_id:
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("VALIDATION_ERROR", "selected_server_id must belong to the same organization as the session.", field="selected_server_id")
            sess["selected_server_id"] = selected_server_id
            mutated = True

        if ip_address is not None:
            if not isinstance(ip_address, str):
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("VALIDATION_ERROR", "ip_address must be a string.", field="ip_address")
            sess["ip_address"] = ip_address
            mutated = True
        if user_agent is not None:
            if not isinstance(user_agent, str):
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("VALIDATION_ERROR", "user_agent must be a string.", field="user_agent")
            sess["user_agent"] = user_agent
            mutated = True

        if mutated:
            sess["updated_at"] = now_iso
            _save("auth_sessions.json", sessions)

    else:
        # No access_token provided: resume an existing active session matching org (+ principal if provided), else create.
        def _sess_active(s):
            if not isinstance(s, dict):
                return False
            if s.get("organization_id") != organization_id:
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt(s.get("expires_at"))
            return (exp is not None and exp > now)

        # principal constraints
        candidate = None
        for s in sessions:
            if not _sess_active(s):
                continue
            if user_id is not None and s.get("user_id") != user_id:
                continue
            if api_client_id is not None and s.get("api_client_id") != api_client_id:
                continue
            # ensure principal validity
            if (s.get("user_id") is None) == (s.get("api_client_id") is None):
                continue
            candidate = s
            break

        if candidate is not None:
            sess = candidate
            # allow setting selected_server_id, ip, ua
            if selected_server_id is not None:
                srv = next((x for x in servers if isinstance(x, dict) and x.get("id") == selected_server_id), None)
                if not srv:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("NOT_FOUND", "Selected server not found.", selected_server_id=selected_server_id)
                if srv.get("organization_id") != organization_id:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("VALIDATION_ERROR", "selected_server_id must belong to the same organization as the session.", field="selected_server_id")
                if sess.get("selected_server_id") != selected_server_id:
                    sess["selected_server_id"] = selected_server_id
                    sess["updated_at"] = now_iso
                    mutated = True
            if ip_address is not None:
                if not isinstance(ip_address, str):
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("VALIDATION_ERROR", "ip_address must be a string.", field="ip_address")
                sess["ip_address"] = ip_address
                sess["updated_at"] = now_iso
                mutated = True
            if user_agent is not None:
                if not isinstance(user_agent, str):
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("VALIDATION_ERROR", "user_agent must be a string.", field="user_agent")
                sess["user_agent"] = user_agent
                sess["updated_at"] = now_iso
                mutated = True
            if mutated:
                _save("auth_sessions.json", sessions)
        else:
            # Create new session. Must specify exactly one principal; if not, choose a working principal from store.
            uid = user_id
            cid = api_client_id

            if uid is None and cid is None:
                # choose an active user in org, else an active api_client in org
                u = next((u for u in users if isinstance(u, dict) and u.get("organization_id") == organization_id and u.get("status") == "active"), None)
                if u:
                    uid = u.get("id")
                else:
                    c = next((c for c in api_clients if isinstance(c, dict) and c.get("organization_id") == organization_id and c.get("status") == "active"), None)
                    if c:
                        cid = c.get("id")
            # validate chosen principal exists & belongs to org
            if uid is not None:
                u = next((u for u in users if isinstance(u, dict) and u.get("id") == uid), None)
                if not u:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("NOT_FOUND", "User not found.", user_id=uid)
                if u.get("organization_id") != organization_id:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("UNAUTHORIZED", "User not in requested organization.", organization_id=organization_id)
                if u.get("status") in ("disabled", "deleted"):
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("UNAUTHORIZED", "User is not active.", user_id=uid)
            elif cid is not None:
                c = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
                if not c:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("NOT_FOUND", "API client not found.", api_client_id=cid)
                if c.get("organization_id") != organization_id:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("UNAUTHORIZED", "API client not in requested organization.", organization_id=organization_id)
                if c.get("status") != "active":
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("UNAUTHORIZED", "API client is not active.", api_client_id=cid)
            else:
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("UNAUTHORIZED", "No eligible principal found to create a session for this organization.")

            # selected_server_id constraint
            if selected_server_id is not None:
                srv = next((x for x in servers if isinstance(x, dict) and x.get("id") == selected_server_id), None)
                if not srv:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("NOT_FOUND", "Selected server not found.", selected_server_id=selected_server_id)
                if srv.get("organization_id") != organization_id:
                    if mutated:
                        _save("auth_sessions.json", sessions)
                    return _err("VALIDATION_ERROR", "selected_server_id must belong to the same organization as the session.", field="selected_server_id")

            sess_id = _new_id("ccc_sess")
            access_handle = access_token if access_token else sess_id  # client-visible token handle
            refresh_handle = refresh_token if refresh_token else _new_id("ccc_rtok")
            exp_dt = _parse_dt(expires_at) if expires_at is not None else (now + datetime.timedelta(hours=1))

            sess = {
                "id": sess_id,
                "organization_id": organization_id,
                "user_id": uid,
                "api_client_id": cid,
                "selected_server_id": selected_server_id,
                # Store handle in access_token_hash field because schema has only that; do NOT hash it.
                "access_token_hash": access_handle,
                "refresh_token_hash": refresh_handle,
                "expires_at": exp_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "status": "active",
                "ip_address": ip_address if isinstance(ip_address, str) else None,
                "user_agent": user_agent if isinstance(user_agent, str) else None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            # Enforce principal xor rule
            if (sess["user_id"] is None) == (sess["api_client_id"] is None):
                if mutated:
                    _save("auth_sessions.json", sessions)
                return _err("VALIDATION_ERROR", "Session must have exactly one principal (user_id or api_client_id).")

            sessions.append(sess)
            mutated = True
            _save("auth_sessions.json", sessions)

    # ---- Build response: org + accessible servers (same org) ----
    accessible_servers = [s for s in servers if isinstance(s, dict) and s.get("organization_id") == organization_id]
    resp = {
        "session": sess,
        "organization": org,
        "servers": accessible_servers,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }
    return resp

def Organizations(access_token, status=None, region=None, plan=None, slug=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0463000" if __import__("os").path.isdir("./environment_mix/0463000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    # Validate
    if not isinstance(access_token, str) or not access_token.strip():
        return _err("UNAUTHORIZED", "access_token is required.", field="access_token")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if region is not None and not isinstance(region, str):
        return _err("VALIDATION_ERROR", "region must be a string.", field="region")
    if plan is not None and not isinstance(plan, str):
        return _err("VALIDATION_ERROR", "plan must be a string.", field="plan")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string.", field="slug")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    sessions = _load("auth_sessions.json")
    orgs = _load("organizations.json")

    # Expire sessions as needed
    mutated = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                mutated = True

    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if access_token == s.get("id") or access_token == s.get("access_token_hash"):
            sess = s
            break
    if not sess:
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Missing/invalid/expired access_token.")
    if sess.get("status") != "active":
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is not active.")
    exp = _parse_dt(sess.get("expires_at"))
    if exp is None or exp <= now:
        if sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = now_iso
            mutated = True
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is expired.")

    if mutated:
        _save("auth_sessions.json", sessions)

    # Determine entitlement: this dataset models sessions as scoped to one org.
    entitled_org_id = sess.get("organization_id")
    rows = [o for o in orgs if isinstance(o, dict) and o.get("id") == entitled_org_id]

    # Apply filters
    if status is not None:
        rows = [o for o in rows if o.get("status") == status]
    if region is not None:
        rows = [o for o in rows if o.get("region") == region]
    if plan is not None:
        rows = [o for o in rows if o.get("plan") == plan]
    if slug is not None:
        rows = [o for o in rows if o.get("slug") == slug]

    rows.sort(key=lambda x: (x.get("id") or ""))

    start = 0
    if cursor:
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break
    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "cursor": cursor,
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def Servers(access_token, organization_id, status=None, environment=None, name=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0463000" if __import__("os").path.isdir("./environment_mix/0463000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = now
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _find_log_collection():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _append_log(fname, endpoint, credential, status_code, message=None, organization_id=None, extra=None):
        if not fname:
            return
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": f"req_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": endpoint,
            "credential": credential,
            "organization_id": organization_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "extra": extra or {}
        })
        _save(fname, rows)

    logf = _find_log_collection()

    # ---- Validation (before auth) ----
    if not isinstance(access_token, str) or not access_token.strip():
        _append_log(logf, "Servers", None, "UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)

    if not isinstance(organization_id, str) or not re.match(r"^ccc_org_[0-9A-Z]{18,}$", organization_id):
        _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "organization_id is malformed.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "organization_id is malformed.", organization_id=organization_id)

    allowed_status = {"provisioning", "online", "offline", "error", "deleted"}
    if status is not None and status not in allowed_status:
        _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "status is invalid.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "status is invalid.", organization_id=organization_id, allowed=list(sorted(allowed_status)))

    # Tool schema uses production/staging/development; datastore uses prod/staging/dev
    env_map = {"production": "prod", "staging": "staging", "development": "dev", "prod": "prod", "dev": "dev"}
    if environment is not None:
        if environment not in ("production", "staging", "development"):
            _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "environment is invalid.", organization_id=organization_id)
            return _err("VALIDATION_ERROR", "environment is invalid.", organization_id=organization_id, allowed=["production", "staging", "development"])
        env_norm = env_map[environment]
    else:
        env_norm = None

    if name is not None and not isinstance(name, str):
        _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "name must be a string.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "name must be a string.", organization_id=organization_id)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "limit must be an integer between 1 and 200.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", organization_id=organization_id)

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _append_log(logf, "Servers", access_token, "VALIDATION_ERROR", "cursor must be a non-empty string if provided.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string if provided.", organization_id=organization_id)

    # ---- Authenticate by matching against stored client-visible value OR id (never hash) ----
    sessions = _load("auth_sessions.json")
    orgs = _load("organizations.json")

    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == organization_id), None)
    if not org:
        _append_log(logf, "Servers", access_token, "NOT_FOUND", "organization not found.", organization_id=organization_id)
        return _err("NOT_FOUND", "organization not found.", organization_id=organization_id)

    if org.get("status") == "deleted":
        _append_log(logf, "Servers", access_token, "UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)

    def _session_matches_token(sess, token):
        # Accept exact match by id OR by stored access_token_hash value
        return sess.get("id") == token or sess.get("access_token_hash") == token

    active_sessions = []
    for s in sessions if isinstance(sessions, list) else []:
        if not isinstance(s, dict):
            continue
        if not _session_matches_token(s, access_token):
            continue
        if s.get("organization_id") != organization_id:
            continue
        # Treat expiry as expired, regardless of stored status
        exp = _parse_dt(s.get("expires_at"))
        if exp is None or exp <= now:
            continue
        if s.get("status") != "active":
            continue
        # Must be exactly one principal type
        if bool(s.get("user_id")) == bool(s.get("api_client_id")):
            continue
        active_sessions.append(s)

    if not active_sessions:
        _append_log(logf, "Servers", access_token, "UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)

    # Choose a working session (any) - for list it just needs to exist and be active.
    sess = sorted(active_sessions, key=lambda x: x.get("created_at") or "")[-1]

    # ---- Read + filter + paginate ----
    servers = _load("servers.json")
    if not isinstance(servers, list):
        servers = []

    rows = [sv for sv in servers if isinstance(sv, dict) and sv.get("organization_id") == organization_id]

    if status is not None:
        rows = [sv for sv in rows if sv.get("status") == status]
    if env_norm is not None:
        rows = [sv for sv in rows if sv.get("environment") == env_norm]
    if name is not None:
        needle = name.lower()
        rows = [sv for sv in rows if isinstance(sv.get("name"), str) and needle in sv["name"].lower()]

    # stable sort by id for pagination
    rows.sort(key=lambda r: (r.get("id") or ""))

    start = 0
    if cursor:
        # cursor is last seen id; return items strictly after it
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None
    has_more = next_cursor is not None and (start + limit) < len(rows)

    out = {
        "servers": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": len(rows)
        },
        "organization_id": organization_id
    }

    _append_log(logf, "Servers", sess.get("id") or access_token, "OK", None, organization_id=organization_id, extra={"returned": len(page)})
    return out

def Update_Server(access_token, server_id, name=None, base_url=None, environment=None, settings=None, status=None, **_extra):
