        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = now
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _find_log_collection():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _append_log(fname, endpoint, credential, status_code, message=None, organization_id=None, extra=None):
        if not fname:
            return
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": f"req_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": endpoint,
            "credential": credential,
            "organization_id": organization_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "extra": extra or {}
        })
        _save(fname, rows)

    logf = _find_log_collection()

    # ---- Validation ----
    if not isinstance(access_token, str) or not access_token.strip():
        _append_log(logf, "Update Server", None, "UNAUTHORIZED", "access_token is missing/invalid/expired.")
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.")

    if not isinstance(server_id, str) or not re.match(r"^ccc_srv_[0-9A-Z]{18,}$", server_id):
        _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "server_id is malformed.")
        return _err("VALIDATION_ERROR", "server_id is malformed.", server_id=server_id)

    if name is None and base_url is None and environment is None and settings is None and status is None:
        _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "No fields to update were provided.")
        return _err("VALIDATION_ERROR", "No fields to update were provided.", server_id=server_id)

    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.")
            return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.", server_id=server_id)

    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.strip():
            _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "base_url must be a non-empty string.")
            return _err("VALIDATION_ERROR", "base_url must be a non-empty string.", server_id=server_id)
        try:
            u = urlparse(base_url)
        except Exception:
            u = None
        if not u or u.scheme not in ("http", "https") or not u.netloc:
            _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "base_url must be a valid http(s) URL.")
            return _err("VALIDATION_ERROR", "base_url must be a valid http(s) URL.", server_id=server_id)

    env_map = {"production": "prod", "staging": "staging", "development": "dev"}
    env_norm = None
    if environment is not None:
        if environment not in ("production", "staging", "development"):
            _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "environment is invalid.")
            return _err("VALIDATION_ERROR", "environment is invalid.", server_id=server_id, allowed=["production", "staging", "development"])
        env_norm = env_map[environment]

    if settings is not None and not isinstance(settings, dict):
        _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "settings must be an object.")
        return _err("VALIDATION_ERROR", "settings must be an object.", server_id=server_id)

    if status is not None:
        if status not in ("online", "offline", "error", "deleted"):
            _append_log(logf, "Update Server", access_token, "VALIDATION_ERROR", "status is invalid.")
            return _err("VALIDATION_ERROR", "status is invalid.", server_id=server_id)

    sessions = _load("auth_sessions.json")
    orgs = _load("organizations.json")
    servers = _load("servers.json")

    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(servers, list):
        servers = []

    def _session_matches_token(sess, token):
        return sess.get("id") == token or sess.get("access_token_hash") == token

    # locate server first (needed for org_id in auth decision & uniqueness rules)
    idx = None
    srv = None
    for i, s in enumerate(servers):
        if isinstance(s, dict) and s.get("id") == server_id:
            idx = i
            srv = s
            break
    if srv is None:
        _append_log(logf, "Update Server", access_token, "NOT_FOUND", "server not found.", extra={"server_id": server_id})
        return _err("NOT_FOUND", "server not found.", server_id=server_id)

    organization_id = srv.get("organization_id")
    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == organization_id), None)
    if not org:
        _append_log(logf, "Update Server", access_token, "NOT_FOUND", "organization not found.", organization_id=organization_id)
        return _err("NOT_FOUND", "organization not found.", organization_id=organization_id)

    if org.get("status") == "deleted":
        _append_log(logf, "Update Server", access_token, "UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)

    # Authenticate active unexpired session in same org
    candidates = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if not _session_matches_token(s, access_token):
            continue
        if s.get("organization_id") != organization_id:
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is None or exp <= now:
            continue
        if s.get("status") != "active":
            continue
        if bool(s.get("user_id")) == bool(s.get("api_client_id")):
            continue
        candidates.append(s)

    if not candidates:
        _append_log(logf, "Update Server", access_token, "UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)
        return _err("UNAUTHORIZED", "access_token is missing/invalid/expired.", organization_id=organization_id)

    sess = sorted(candidates, key=lambda x: x.get("created_at") or "")[-1]

    # ---- Constraints & transitions ----
    # Uniqueness: (organization_id, name) and (organization_id, base_url)
    if name is not None:
        for other in servers:
            if not isinstance(other, dict) or other.get("id") == server_id:
                continue
            if other.get("organization_id") == organization_id and other.get("name") == name:
                _append_log(logf, "Update Server", sess.get("id") or access_token, "CONFLICT", "Server name must be unique within the organization.", organization_id=organization_id)
                return _err("CONFLICT", "Server name must be unique within the organization.", organization_id=organization_id, field="name")

    if base_url is not None:
        for other in servers:
            if not isinstance(other, dict) or other.get("id") == server_id:
                continue
            if other.get("organization_id") == organization_id and other.get("base_url") == base_url:
                _append_log(logf, "Update Server", sess.get("id") or access_token, "CONFLICT", "base_url must be unique within the organization.", organization_id=organization_id)
                return _err("CONFLICT", "base_url must be unique within the organization.", organization_id=organization_id, field="base_url")

    # Lifecycle transitions: provisioning/online/offline/error/deleted
    transitions = {
        "provisioning": {"online", "error", "deleted"},
        "online": {"offline", "error", "deleted"},
        "offline": {"online", "error", "deleted"},
        "error": {"offline", "deleted"},
        "deleted": set()
    }
    current_status = srv.get("status")
    if status is not None:
        if current_status not in transitions:
            _append_log(logf, "Update Server", sess.get("id") or access_token, "INVALID_TRANSITION", "Current server status is invalid.", organization_id=organization_id)
            return _err("INVALID_TRANSITION", "Current server status is invalid.", server_id=server_id, from_status=current_status, to_status=status)
        if status == current_status:
            # idempotent: allow, but must still have some other effect or return NOT_FOUND? Here effect may be other fields; if only status and same -> no-op invalid.
            if name is None and base_url is None and env_norm is None and settings is None:
                _append_log(logf, "Update Server", sess.get("id") or access_token, "VALIDATION_ERROR", "Requested status is the same as current status and no other updates were provided.", organization_id=organization_id)
                return _err("VALIDATION_ERROR", "Requested status is the same as current status and no other updates were provided.", server_id=server_id)
        else:
            if status not in transitions.get(current_status, set()):
                _append_log(logf, "Update Server", sess.get("id") or access_token, "INVALID_TRANSITION", "Requested status transition is not allowed.", organization_id=organization_id)
                return _err("INVALID_TRANSITION", "Requested status transition is not allowed.", server_id=server_id, from_status=current_status, to_status=status, allowed=list(sorted(transitions.get(current_status, set()))))

    # ---- Apply mutation ----
    changed = False
    srv2 = dict(srv)

    if name is not None and srv2.get("name") != name:
        srv2["name"] = name
        changed = True
    if base_url is not None and srv2.get("base_url") != base_url:
        srv2["base_url"] = base_url
        changed = True
    if env_norm is not None and srv2.get("environment") != env_norm:
        srv2["environment"] = env_norm
        changed = True
    if settings is not None and srv2.get("settings") != settings:
        srv2["settings"] = settings
        changed = True
    if status is not None and srv2.get("status") != status:
        srv2["status"] = status
        changed = True

    if not changed:
        _append_log(logf, "Update Server", sess.get("id") or access_token, "VALIDATION_ERROR", "No changes detected.", organization_id=organization_id)
        return _err("VALIDATION_ERROR", "No changes detected.", server_id=server_id)

    srv2["updated_at"] = _iso(now)
    servers[idx] = srv2
    _save("servers.json", servers)

    _append_log(logf, "Update Server", sess.get("id") or access_token, "OK", None, organization_id=organization_id, extra={"server_id": server_id})
    return {"server": srv2}

