        return _err("CONFLICT", "API client name must be unique within the organization.", organization_id=organization_id, field="name")

    # unique(client_key)
    existing_keys = {c.get("client_key") for c in api_clients if isinstance(c, dict)}
    def _gen_key():
        # client-visible key; not a hash
        return "ccc_key_" + secrets.token_urlsafe(18).replace("-", "").replace("_", "")[:24]
    client_key = _gen_key()
    for _ in range(10):
        if client_key not in existing_keys:
            break
        client_key = _gen_key()
    if client_key in existing_keys:
        _append_log(logf, "Create API Client", sess.get("id") or access_token, "CONFLICT", "Unable to allocate unique client_key.", organization_id=organization_id)
        return _err("CONFLICT", "Unable to allocate unique client_key.", organization_id=organization_id)

    # one-time secret returned only now; store only hash
    client_secret = secrets.token_urlsafe(32)
    secret_hash = "sha256:" + hashlib.sha256(client_secret.encode("utf-8")).hexdigest()

    # generate id in convention
    def _new_id(prefix, rows):
        mx = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            if isinstance(rid, str) and rid.startswith(prefix):
                mx += 1
        return f"{prefix}{int(time.time()*1000)}_{mx+1}"

    new_id = _new_id("ccc_cli_", api_clients)
    created = {
        "id": new_id,
        "organization_id": organization_id,
        "name": name,
        "client_key": client_key,
        "client_secret_hash": secret_hash,
        "scopes": scopes,
        "status": "active",
        "last_used_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now)
    }

    api_clients.append(created)
    _save("api_clients.json", api_clients)

    # Return one-time client_secret in response only
    resp = {"api_client": dict(created)}
    resp["api_client"]["client_secret"] = client_secret

    _append_log(logf, "Create API Client", sess.get("id") or access_token, "OK", None, organization_id=organization_id, extra={"api_client_id": new_id})
    return resp

def Update_API_Client(access_token, api_client_id, name=None, scopes=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0463000" if __import__("os").path.isdir("./environment_mix/0463000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    # Validate
    if not isinstance(access_token, str) or not access_token.strip():
        return _err("UNAUTHORIZED", "access_token is required.", field="access_token")
    if not isinstance(api_client_id, str) or not re.match(r"^ccc_cli_[0-9A-Z]{18,}$", api_client_id or ""):
        return _err("VALIDATION_ERROR", "api_client_id is malformed.", field="api_client_id")

    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200)):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 chars.", field="name")

    allowed_scopes = {
        "org:read", "org:write",
        "users:read", "users:write",
        "servers:read", "servers:write",
        "sessions:read", "sessions:write",
        "api_clients:read", "api_clients:write",
    }
    if scopes is not None:
        if not isinstance(scopes, list) or len(scopes) < 1:
            return _err("VALIDATION_ERROR", "scopes must be a non-empty array.", field="scopes")
        for s in scopes:
            if not isinstance(s, str) or s not in allowed_scopes:
                return _err("VALIDATION_ERROR", "Invalid scope in scopes.", field="scopes", scope=s)

    if status is not None and status not in ("active", "revoked", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    sessions = _load("auth_sessions.json")
    api_clients = _load("api_clients.json")

    # Expire sessions as needed
    mutated_sessions = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                mutated_sessions = True

    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if access_token == s.get("id") or access_token == s.get("access_token_hash"):
            sess = s
            break
    if not sess:
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Missing/invalid/expired access_token.")
    if sess.get("status") != "active":
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is not active.")
    exp = _parse_dt(sess.get("expires_at"))
    if exp is None or exp <= now:
        if sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = now_iso
            mutated_sessions = True
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is expired.")

    client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == api_client_id), None)
    if not client:
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("NOT_FOUND", "API client not found.", api_client_id=api_client_id)

    # Entitlement: session org must match api_client org
    if sess.get("organization_id") != client.get("organization_id"):
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session not authorized for requested organization.", organization_id=client.get("organization_id"))

    changed = False

    if name is not None and name != client.get("name"):
        # unique(organization_id, name)
        if any(isinstance(c, dict) and c.get("id") != client.get("id") and c.get("organization_id") == client.get("organization_id") and c.get("name") == name for c in api_clients):
            if mutated_sessions:
                _save("auth_sessions.json", sessions)
            return _err("CONFLICT", "API client name must be unique within the organization.", field="name")
        client["name"] = name
        changed = True

    if scopes is not None and scopes != client.get("scopes"):
        client["scopes"] = scopes
        changed = True

    if status is not None:
        allowed = {
            "active": ["revoked", "deleted"],
            "revoked": ["active", "deleted"],
            "deleted": [],
        }
        cur = client.get("status")
        if cur not in allowed:
            if mutated_sessions:
                _save("auth_sessions.json", sessions)
            return _err("VALIDATION_ERROR", "API client has unknown current status.", current_status=cur)
        if status != cur:
            if status not in allowed[cur]:
                if mutated_sessions:
                    _save("auth_sessions.json", sessions)
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.", from_status=cur, to_status=status)
            client["status"] = status
            changed = True

            # Business rule: if transitioning to revoked, revoke all active sessions with api_client_id within same transaction
            if status == "revoked":
                for s in sessions:
                    if not isinstance(s, dict):
                        continue
                    if s.get("api_client_id") == api_client_id and s.get("status") == "active":
                        s["status"] = "revoked"
                        s["updated_at"] = now_iso
                        mutated_sessions = True

    if not changed:
        if mutated_sessions:
            _save("auth_sessions.json", sessions)
        return _err("NOT_FOUND", "No changes applied (fields identical or not provided).")

    client["updated_at"] = now_iso
    _save("api_clients.json", api_clients)
    if mutated_sessions:
        _save("auth_sessions.json", sessions)

    return {"data": client, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def Who_Am_I(access_token, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0463000" if __import__("os").path.isdir("./environment_mix/0463000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    if not isinstance(access_token, str) or not access_token.strip():
        return _err("UNAUTHORIZED", "access_token is required.", field="access_token")

    sessions = _load("auth_sessions.json")
    orgs = _load("organizations.json")
    users = _load("users.json")
    api_clients = _load("api_clients.json")
    servers = _load("servers.json")

    # Expire active sessions that are now past expires_at
    mutated = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                mutated = True

    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if access_token == s.get("id") or access_token == s.get("access_token_hash"):
            sess = s
            break
    if not sess:
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Missing/invalid/expired access_token.")

    # Deny revoked; treat expired at read time
    exp = _parse_dt(sess.get("expires_at"))
    if sess.get("status") == "revoked":
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is revoked.")
    if exp is None or exp <= now or sess.get("status") == "expired":
        if sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = now_iso
            mutated = True
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is expired.")
    if sess.get("status") != "active":
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is not active.")

    uid = sess.get("user_id")
    cid = sess.get("api_client_id")
    if (uid is None) == (cid is None):
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session principal is invalid (must be user or api_client).")

    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == sess.get("organization_id")), None)
    if not org:
        if mutated:
            _save("auth_sessions.json", sessions)
        return _err("NOT_FOUND", "Organization not found for session.", organization_id=sess.get("organization_id"))

    principal = None
    principal_type = None
    effective_scopes = []

    if uid is not None:
        principal_type = "user"
        principal = next((u for u in users if isinstance(u, dict) and u.get("id") == uid), None)
        if not principal:
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "User principal not found for session.", user_id=uid)
        # User scopes not modeled; infer coarse scopes by role (best-effort)
        role = principal.get("role")
        if role in ("owner", "admin"):
            effective_scopes = sorted([
                "org:read", "org:write",
                "users:read", "users:write",
                "servers:read", "servers:write",
                "sessions:read", "sessions:write",
                "api_clients:read", "api_clients:write",
            ])
        elif role in ("member",):
            effective_scopes = sorted(["org:read", "servers:read", "api_clients:read", "sessions:read", "users:read"])
        else:
            effective_scopes = sorted(["org:read", "servers:read", "api_clients:read", "sessions:read"])
    else:
        principal_type = "api_client"
        principal = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        if not principal:
            if mutated:
                _save("auth_sessions.json", sessions)
            return _err("UNAUTHORIZED", "API client principal not found for session.", api_client_id=cid)
        effective_scopes = principal.get("scopes") if isinstance(principal.get("scopes"), list) else []

    selected_server = None
    if sess.get("selected_server_id"):
        selected_server = next((sv for sv in servers if isinstance(sv, dict) and sv.get("id") == sess.get("selected_server_id")), None)

    if mutated:
        _save("auth_sessions.json", sessions)

    return {
        "session": sess,
        "principal": {"type": principal_type, "data": principal},
        "organization": org,
        "selected_server": selected_server,
        "effective_scopes": effective_scopes,
        "quota": {
            "plan": org.get("plan"),
            "rate_limit": None,
            "usage": None
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }
